"""Command line driver for the jd-compatible JSON diff implementation."""
from __future__ import annotations

import json
import os
import sys

VERSION = "jd version 2.5.0"


def _usage():
    return """Usage: jd [OPTION]... FILE1 [FILE2]
Diff and patch JSON files.

Prints the diff of FILE1 and FILE2 to STDOUT.
When FILE2 is omitted the second input is read from STDIN.
When patching (-p) FILE1 is a diff.

Options:
  -color       Print color diff.
  -color-words Print color diff with character-level highlighting.
  -p           Apply patch FILE1 to FILE2 or STDIN.
  -o=FILE3     Write to FILE3 instead of STDOUT.
  -opts='[]'   JSON array of comparison options.
  -set         Treat arrays as sets.
  -mset        Treat arrays as multisets.
  -setkeys     Keys to identify set objects.
  -yaml        Read and write YAML instead of JSON.
  -precision=N Maximum absolute difference for numbers to be equal.
  -f=FORMAT    Diff format: jd, patch, merge.
  -t=FORMATS   Translate formats, e.g. jd2patch or yaml2json.
  -version     Print version and exit.
"""


def _parse_args(argv):
    flags = {"color": False, "color_words": False, "patch": False,
             "yaml": False, "set": False, "mset": False, "version": False,
             "git": False, "opts": "[]", "precision": None, "setkeys": None,
             "format": "jd", "translate": None, "output": None, "port": None}
    files = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--":
            files.extend(argv[i + 1:]); break
        if not a.startswith("-") or a == "-":
            files.append(a); i += 1; continue
        key, eq, value = a.partition("=")
        name = key.lstrip("-")
        bools = {"color": "color", "color-words": "color_words", "p": "patch",
                 "yaml": "yaml", "set": "set", "mset": "mset",
                 "version": "version", "git-diff-driver": "git", "v2": "v2"}
        vals = {"opts": "opts", "precision": "precision", "setkeys": "setkeys",
                "f": "format", "t": "translate", "o": "output", "port": "port"}
        if name in bools:
            if eq:
                raise ValueError("flag does not take a value: " + key)
            flags[bools[name]] = True
        elif name in vals:
            if not eq:
                i += 1
                if i >= len(argv): raise ValueError("flag needs an argument: " + key)
                value = argv[i]
            target = vals[name]
            if target == "precision":
                try: value = float(value)
                except ValueError: raise ValueError("invalid precision")
            if target == "port":
                try: value = int(value)
                except ValueError: raise ValueError("invalid port")
            flags[target] = value
        else:
            raise ValueError("flag provided but not defined: " + key)
        i += 1
    return flags, files


