def _write(path, value):
    if path:
        with open(path, "w", encoding="utf-8") as f: f.write(value)
    else: sys.stdout.write(value)


def _apply_jd_patch(doc, patch):
    """Apply the common scalar/object/array subset of jd's line patch syntax."""
    import copy
    value = copy.deepcopy(doc)
    hunks = []
    path = None
    rows = []
    for line in patch.splitlines():
        if line.startswith("@ "):
            if path is not None: hunks.append((path, rows))
            path, rows = json.loads(line[2:]), []
        elif line.startswith("^ "):
            continue
        elif line.startswith(("  ", "+ ", "- ")) and path is not None:
            rows.append((line[:1], json.loads(line[2:])))
    if path is not None: hunks.append((path, rows))
    for path, rows in hunks:
        if not path:
