    if len(files) > 2 or (not files and not flags["translate"]):
        sys.stdout.write("\n" + _usage() + "\nVersion: 2.5.0\n\n"); return 2
    if flags["translate"]:
        from translate import translate
        source = _read(files[0]) if files else sys.stdin.read()
        result = translate(source, flags["translate"], yaml_mode=flags["yaml"])
