"""Format conversion helpers for the jd command line interface."""
import json


def _compact(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def _pointer(path):
    return "/" + "/".join(str(x).replace("~", "~0").replace("/", "~1") for x in path)


def _read_hunks(source):
    hunks, path, rows = [], None, []
    for line in source.splitlines():
        if line.startswith("@ "):
            if path is not None:
                hunks.append((path, rows))
            path, rows = json.loads(line[2:]), []
        elif line.startswith("^ "):
            continue
        elif path is not None and line[:2] in ("  ", "+ ", "- "):
            rows.append((line[0], json.loads(line[2:])))
    if path is not None:
        hunks.append((path, rows))
    return hunks


def _jd_to_patch(source):
    result = []
    for path, rows in _read_hunks(source):
        pointer = _pointer(path)
        old = [v for op, v in rows if op == "-"]
        new = [v for op, v in rows if op == "+"]
        if old:
            result.append({"op": "test", "path": pointer, "value": old[0]})
            result.append({"op": "remove", "path": pointer, "value": old[0]})
        for value in new:
            result.append({"op": "add", "path": pointer, "value": value})
    return _compact(result)


def _patch_to_jd(source):
    operations = json.loads(source)
    groups = []
    lookup = {}
    for op in operations:
        kind, pointer = op.get("op"), op.get("path", "")
        path = [] if pointer == "" else [p.replace("~1", "/").replace("~0", "~") for p in pointer.lstrip("/").split("/")]
        if kind == "test":
            continue
        identity = _compact(path)
        if identity not in lookup:
            lookup[identity] = [path, []]
            groups.append(lookup[identity])
        rows = lookup[identity][1]
        if kind in ("remove", "replace"):
            if "value" in op:
                rows.append(("-", op["value"]))
        if kind in ("add", "replace"):
            rows.append(("+", op.get("value")))
    out = []
    for path, rows in groups:
        out.append("@ " + _compact(path))
        out.extend(mark + " " + _compact(value) for mark, value in rows)
    return "\n".join(out) + ("\n" if out else "")


def _merge_to_jd(value):
    out = ['^ {"Merge":true}']

    def walk(node, path):
        if isinstance(node, dict):
            for key, child in node.items():
                walk(child, path + [key])
        else:
            out.append("@ " + _compact(path))
            out.append("+ " + _compact(node))

    if isinstance(value, dict):
        walk(value, [])
    else:
        out.append("@ []")
        out.append("+ " + _compact(value))
    return "\n".join(out) + "\n"


def _json_to_yaml(value, indent=0):
    # A small serializer for JSON-compatible values; YAML is a JSON subset.
    pad = " " * indent
    if isinstance(value, dict):
        lines = []
        for key, child in value.items():
            k = str(key) if str(key).replace("_", "a").isalnum() else _compact(str(key))
            if isinstance(child, (dict, list)) and child:
                lines.append(pad + k + ":")
                lines.append(_json_to_yaml(child, indent + 4))
            else:
                lines.append(pad + k + ": " + _yaml_scalar(child))
        return "\n".join(lines)
    if isinstance(value, list):
        lines = []
        for child in value:
            if isinstance(child, (dict, list)) and child:
                lines.append(pad + "-")
                lines.append(_json_to_yaml(child, indent + 4))
            else:
                lines.append(pad + "- " + _yaml_scalar(child))
        return "\n".join(lines)
